using System;
using System.IO;
using System.Linq;
using HyperTizen.Bulbs.Matter;
using Newtonsoft.Json.Linq;
using Org.BouncyCastle.Crypto;
using Xunit;

namespace HyperTizen.Bulbs.Tests
{
    /// <summary>Byte-for-byte checks against fixtures/matter-vectors.json, generated by matter.js 0.18 (gen-vectors.mjs).</summary>
    public class MatterCodecTests
    {
        private static readonly JObject V = JObject.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "fixtures", "matter-vectors.json")));
        private static byte[] Hex(JToken t) => Convert.FromHexString((string)t);
        private const int Anon = TlvWriter.Anonymous;

        [Theory]
        [InlineData("MoveToHueAndSaturation")]
        [InlineData("MoveToLevelWithOnOff")]
        [InlineData("MoveToColorTemperature")]
        [InlineData("MoveToLevel")]
        public void Tlv_InvokeRequest_MatchesMatterJs(string name)
        {
            var vec = V["tlv"].First(t => (string)t["name"] == name);
            var cluster = (ulong)vec["cluster"];
            var command = (ulong)vec["command"];
            var fields = ((JObject)vec["fields"]).Properties().Select(p => (ulong)p.Value).ToArray();

            var w = new TlvWriter();
            w.StartStructure(Anon);
            w.Put(0, false);                 // suppressResponse
            w.Put(1, false);                 // timedRequest
            w.StartArray(2);                 // invokeRequests
            w.StartStructure(Anon);          // CommandDataIB
            w.StartList(0);                  // CommandPathIB
            w.Put(0, 1UL);
            w.Put(1, cluster);
            w.Put(2, command);
            w.EndContainer();
            w.StartStructure(1);             // commandFields
            for (int i = 0; i < fields.Length; i++) w.Put(i, fields[i]);
            w.EndContainer();
            w.EndContainer();
            w.EndContainer();
            w.Put(255, 11UL);                // interactionModelRevision, as matter.js sends it
            w.EndContainer();
            Assert.Equal(Hex(vec["hex"]), w.ToArray());

            // and read matter.js's bytes back
            var r = new TlvReader(Hex(vec["hex"]));
            Assert.True(r.Next()); Assert.Equal(TlvType.Structure, r.Type); r.EnterContainer();
            Assert.True(r.Next()); Assert.Equal(0, r.Tag); Assert.Equal(TlvType.Bool, r.Type);
            Assert.True(r.Next()); Assert.Equal(1, r.Tag);
            Assert.True(r.Next()); Assert.Equal(2, r.Tag); Assert.Equal(TlvType.Array, r.Type); r.EnterContainer();
            Assert.True(r.Next()); Assert.Equal(Anon, r.Tag); r.EnterContainer();
            Assert.True(r.Next()); Assert.Equal(TlvType.List, r.Type); r.EnterContainer();
            Assert.True(r.Next()); Assert.Equal(1UL, r.GetUInt());
            Assert.True(r.Next()); Assert.Equal(cluster, r.GetUInt());
            Assert.True(r.Next()); Assert.Equal(command, r.GetUInt());
            Assert.False(r.Next()); r.ExitContainer();
            Assert.True(r.Next()); Assert.Equal(1, r.Tag); r.EnterContainer();
            Assert.True(r.Next()); Assert.Equal(fields[0], r.GetUInt());
            r.ExitContainer();               // skips the remaining fields
            r.ExitContainer();
            Assert.False(r.Next()); r.ExitContainer();
            Assert.True(r.Next()); Assert.Equal(255, r.Tag); Assert.Equal(11UL, r.GetUInt());
            Assert.False(r.Next()); r.ExitContainer();
            Assert.False(r.Next());
        }

        [Fact]
        public void Tlv_RoundTrip_SignedBytesString()
        {
            var w = new TlvWriter();
            w.StartStructure(Anon);
            w.Put(1, -2L);
            w.Put(2, new byte[300]);
            w.Put(3, "hi");
            w.EndContainer();
            var bytes = w.ToArray();
            Assert.Equal(new byte[] { 0x15, 0x20, 0x01, 0xfe, 0x31, 0x02, 0x2c, 0x01 }, bytes.Take(8).ToArray());

            var r = new TlvReader(bytes);
            r.Next(); r.EnterContainer();
            r.Next(); Assert.Equal(TlvType.SignedInt, r.Type);
            r.Next(); Assert.Equal(TlvType.Bytes, r.Type); Assert.Equal(300, r.GetBytes().Length);
            r.Next(); Assert.Equal(TlvType.Utf8, r.Type); Assert.Equal("hi"u8.ToArray(), r.GetBytes());
            Assert.False(r.Next());
        }

        [Fact]
        public void ProtocolHeader_MatchesMatterJs()
        {
            var vec = V["protocolHeader"];
            var h = new ProtocolHeader
            {
                Initiator = true, NeedsAck = true, Opcode = (byte)vec["opcode"],
                ExchangeId = (ushort)vec["exchangeId"], ProtocolId = (ushort)vec["protocolId"], AckCounter = (uint)vec["ackCounter"],
            };
            Assert.Equal(Hex(vec["hex"]), h.Encode());

            var d = ProtocolHeader.Decode(Hex(vec["hex"]).Concat(new byte[] { 0x15 }).ToArray(), out var body);
            Assert.Equal(h, d);
            Assert.Equal(10, body);
        }

        private static readonly JToken M = V["message"];
        private static ulong SourceNode => ulong.Parse((string)M["sourceNodeId"]);

        [Fact]
        public void Message_Encrypt_MatchesMatterJs()
        {
            var d = MessageCodec.EncodeSecured((ushort)M["sessionId"], (uint)M["counter"], Hex(M["plaintext"]), Hex(M["key"]), SourceNode);
            Assert.Equal(Hex(M["datagram"]), d);
        }

        [Fact]
        public void Message_Decrypt_RoundTrip()
        {
            var plain = MessageCodec.DecodeSecured(Hex(M["datagram"]), Hex(M["key"]), SourceNode, out var h);
            Assert.Equal(Hex(M["plaintext"]), plain);
            Assert.Equal((ushort)M["sessionId"], h.SessionId);
            Assert.Equal((uint)M["counter"], h.Counter);
            Assert.Null(h.SourceNodeId);

            var p = ProtocolHeader.Decode(plain, out var body);
            Assert.Equal(0x08, p.Opcode);
            Assert.Equal(0xabcd, p.ExchangeId);
            Assert.Equal(Hex(V["tlv"][0]["hex"]), plain.Skip(body).ToArray());
        }

        [Fact]
        public void Message_TamperedTag_Throws()
        {
            var d = Hex(M["datagram"]);
            d[d.Length - 1] ^= 1;
            Assert.Throws<InvalidCipherTextException>(() => MessageCodec.DecodeSecured(d, Hex(M["key"]), SourceNode, out _));
        }

        [Fact]
        public void Hkdf_MatchesMatterJs()
        {
            var h = V["hkdf"];
            Assert.Equal(Hex(h["okm"]), SessionCrypto.Hkdf(Hex(h["ikm"]), Hex(h["salt"]), Hex(h["info"]), (int)h["length"]));
        }

        [Fact]
        public void Ecdh_MatchesMatterJs()
        {
            var e = V["ecdh"];
            Assert.Equal(Hex(e["shared"]), SessionCrypto.EcdhP256(Hex(e["privA"]), Hex(e["pubB"])));
            Assert.Equal(Hex(e["shared"]), SessionCrypto.EcdhP256(Hex(e["privB"]), Hex(e["pubA"])));
        }

        [Fact]
        public void Verify_MatterJsSignature()
        {
            var s = V["ecdsa"];
            byte[] pub = Hex(s["pub"]), msg = Hex(s["msg"]), sig = Hex(s["sig"]);
            Assert.True(SessionCrypto.VerifyP256(pub, msg, sig));
            msg[0] ^= 1;
            Assert.False(SessionCrypto.VerifyP256(pub, msg, sig));
            msg[0] ^= 1;

            // our own signature: raw r||s that verifies with the matching public key
            var own = SessionCrypto.SignP256(Hex(V["ecdh"]["privA"]), msg);
            Assert.Equal(64, own.Length);
            Assert.True(SessionCrypto.VerifyP256(pub, msg, own));
        }

        [Fact]
        public void Sha256_And_Hmac_MatchMatterJs()
        {
            Assert.Equal(Hex(V["sha256"]["digest"]), SessionCrypto.Sha256(Hex(V["sha256"]["msg"])));
            var m = V["hmacSha256"];
            Assert.Equal(Hex(m["mac"]), SessionCrypto.HmacSha256(Hex(m["key"]), Hex(m["msg"])));
        }
    }
}
